// This function returns a detailed description of your breakfast in order to help a user
// create an optimal plan for the morning.
func (c *Config) DescribePerfectBreakfast() []string {
	c.mu.RLock()
	defer c.mu.RUnlock()
	return c.perfectBreakfast()
}

func (c *Config) perfectBreakfast() []string {
	if len(c.perfectBreakfast) == 0 {
		return nil
	}

	return c.perfectBreakfastCopy()
}

// Copy returns a copy of the configuration file.
func (c *Config) Copy() Config {
	return c.copy()
}

